(()=>{
const en=document.documentElement.lang==='en',t=(zh,english)=>en?english:zh,$=id=>document.getElementById(id),outside=$('stage-outside');if(!outside)return;
const form=$('commute'),results=$('advice').parentElement,connections=$('live-transit'),context=$('journey-context');
const root=document.createElement('section');root.className='travel-flow';root.innerHTML=`<header class="flow-summary"><div><p class="gg-overline">TRAVEL / ONE CONNECTED PLAN</p><h2 id="flowDestination"></h2><p id="flowContext"></p></div><span class="flow-status">${t('班次耗时：示例 · 路线：本地快照','Times: illustrative · Routes: saved snapshot')}</span></header><nav id="travelFlowNav" aria-label="${t('通勤规划步骤','Travel planning steps')}"></nav><div id="travelFlowPages"></div><footer class="flow-footer"><button id="flowBack" type="button" class="outline"></button><span id="flowPosition"></span><button id="flowNext" type="button" class="primary"></button></footer>`;outside.prepend(root);
const defs=[['trip',t('确认行程','Confirm trip'),t('时间和目的地，先确认一次。','Confirm time and destination once.')],['mode',t('选择方式','Choose mode'),t('先看建议，再比较公交和火车。','Review advice, then compare bus and train.')],['route',t('核对线路','Check route'),t('线路、方向和上下车站放在一起。','Keep line, direction and stops together.')],['weather',t('天气与出发','Weather & go'),t('检查天气，再衔接校园内最后一段。','Check the weather, then connect the final campus walk.')]];const pages={},buttons={};let active=0,mode=null;
defs.forEach(([id,title,desc],i)=>{const b=document.createElement('button');b.type='button';b.innerHTML=`<span>0${i+1}</span><b>${title}</b>`;b.onclick=()=>show(id);$('travelFlowNav').append(b);buttons[id]=b;const page=document.createElement('section');page.className='travel-flow-page';page.id='travel-flow-'+id;const heading=document.createElement('div');heading.className='flow-step-intro';const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=desc;heading.append(h,p);page.append(heading);$('travelFlowPages').append(page);pages[id]=page;});
pages.trip.append(form);form.querySelector('.eyebrow').hidden=true;form.querySelector('h2').hidden=true;
pages.mode.append(results);results.querySelector('.eyebrow').hidden=true;
pages.route.append(connections);connections.querySelector('h2').hidden=true;connections.querySelector('.eyebrow').hidden=true;
const fav=$('busFavourites');const favDrawer=document.createElement('details');favDrawer.className='flow-bus-drawer';favDrawer.open=true;const fs=document.createElement('summary');fs.textContent=t('常用公交路线 · 站点地图与站序','Saved bus routes · map & stop sequence');fav.before(favDrawer);favDrawer.append(fs,fav);
// Separate the existing forecast from its origin map, preserving all controls and listeners.
const contextGrid=context.querySelector('.context-grid'),mapColumn=contextGrid.children[0],forecast=contextGrid.children[1];pages.weather.append(forecast);const originDrawer=document.createElement('details');originDrawer.className='flow-origin-drawer';originDrawer.innerHTML=`<summary>${t('调整天气查询起点 · 地图与坐标','Adjust forecast origin · map & coordinates')}</summary>`;originDrawer.append(mapColumn);pages.weather.append(originDrawer);
const info=document.createElement('details');info.className='flow-origin-drawer';info.innerHTML=`<summary>${t('地图、天气来源与使用说明','Map, forecast sources & guidance')}</summary>`;info.append(context);pages.weather.append(info);
const continuation=document.createElement('div');continuation.className='flow-ready';continuation.innerHTML=`<h3>${t('下一步：从到达点走到教学楼','Next: arrival point to campus building')}</h3><p id="flowReadyText"></p><p>${t('公交站或停车点仍可在 Campus 页面核对。无需在此重新输入教学楼。','Verify bus stops or parking in Campus. The selected building carries over.')}</p>`;pages.weather.append(continuation);
const oldGrid=outside.querySelector('.travel-workspace');if(oldGrid&&!oldGrid.children.length)oldGrid.remove();
function summary(){const dest=$('building').selectedOptions[0]?.textContent||'';$('flowDestination').textContent=dest;$('flowContext').textContent=`${$('area').value} → ${dest} · ${$('commuteDate').value} · ${$('classStart').value} ${t('上课（英国时间）','class (UK time)')}`;$('flowReadyText').textContent=($('campusSelection')?.textContent||dest);}
function show(id){const n=defs.findIndex(d=>d[0]===id);if(n<0)return;active=n;for(const [key,p]of Object.entries(pages)){p.hidden=key!==id;buttons[key].setAttribute('aria-current',key===id?'step':'false');}root.dataset.step=id;$('flowBack').hidden=n===0;$('flowBack').textContent='← '+t('上一步','Back');$('flowPosition').textContent=`${n+1} / ${defs.length}`;$('flowNext').textContent=n===3?t('进入校园导航 →','Continue to campus →'):t('下一步：','Next: ')+defs[n+1][1]+' →';summary();window.dispatchEvent(new Event('resize'));}
$('flowBack').onclick=()=>show(defs[Math.max(0,active-1)][0]);$('flowNext').onclick=()=>{if(active===0){if(!form.reportValidity())return;form.requestSubmit();return;}if(active===3){document.querySelector('#arrivalFlow nav button:nth-child(3)').click();return;}show(defs[active+1][0]);};form.addEventListener('submit',()=>{if(form.checkValidity())show('mode');});
window.GreenGoTravelFlow={show};window.addEventListener('greengo:mode-selected',e=>{mode=e.detail.mode;favDrawer.open=['bus','combo'].includes(mode);show('route');});
['area','building','commuteDate','classStart'].forEach(id=>$(id).addEventListener('change',summary));new MutationObserver(summary).observe($('campusSelection'),{childList:true,subtree:true});
originDrawer.addEventListener('toggle',()=>{if(originDrawer.open)window.dispatchEvent(new Event('resize'));});favDrawer.addEventListener('toggle',()=>window.dispatchEvent(new Event('resize')));show('trip');
})();
